"""Generate the agreed logical image map; physical placement is separate."""
import argparse,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
PROFILE_FUNCTIONS="  function valid_constant(kind:constant_kind_t;value:wide_t) return boolean is\n  begin\n    case kind is\n      when CONST_WEIGHT | CONST_PROFILE => return true;\n      when CONST_BIAS => return fits(value,C_ACC_BITS);\n      when CONST_MULTIPLIER => return fits(value,C_MULT_BITS) and value>0;\n      when CONST_GAMMA | CONST_POSITION | CONST_PWL => return fits(value,C_STATE_BITS);\n      when CONST_SHIFT => return fits(value,8) and value>=-50 and value<=50;\n      when CONST_EXP => return unsigned(value)<=2**C_EXP_FRAC;\n      when CONST_RSQRT => return unsigned(value)<=2**30;\n    end case;\n  end;\n  function number(p:profile_t;i:natural) return natural is\n  begin\n    if p(i)<0 or p(i)>2**30 then return 2**30;else return to_integer(p(i));end if;\n  end;\n  function valid_profile(p:profile_t;identity:identity_t) return boolean is\n    variable mode,depth,classes,base,bits,n,k,span : natural;\n  begin\n    if unsigned(p(0))/=resize(C_IMAGE_MAGIC,64) or p(1)/=131072 or p(2)/=2 or number(p,3)>1 or number(p,4)>2 then return false;end if;\n    mode:=number(p,4);depth:=number(p,5);classes:=6;if p(3)=1 then classes:=35;end if;\n    if p(6)/=32 or p(7)/=128 or p(8)/=4 or p(9)/=256 or number(p,10)/=classes or p(13)/=4 or number(p,14)>16 or p(15)/=185364 then return false;end if;\n    if mode=0 and (depth/=4 or p(11)/=8 or p(12)/=0) then return false;end if;\n    if mode=1 and (depth/=4 or p(11)/=6 or p(12)/=1) then return false;end if;\n    if mode=2 and (depth/=2 or p(11)/=4 or p(12)/=1) then return false;end if;\n    for i in 0 to 8 loop if number(p,16+i)>region_words(constant_kind_t'val(i)) then return false;end if;end loop;\n    if number(p,19)/=(depth*2+1)*128 or p(20)/=4096 or p(22)/=4097 or p(23)/=1024 or p(24)/=9 then return false;end if;\n    for i in 25 to 31 loop if p(i)/=0 then return false;end if;end loop;\n    for i in 52 to 63 loop if p(i)/=0 then return false;end if;end loop;\n    for i in 0 to 7 loop\n      if shift_right(unsigned(p(32+i)),32)/=0 or std_logic_vector(p(32+i)(31 downto 0))/=identity(32*i+31 downto 32*i) then return false;end if;\n    end loop;\n    for i in 0 to 11 loop\n      if i<depth*3 then if number(p,40+i)>16 then return false;end if;\n      elsif p(40+i)/=0 then return false;end if;\n    end loop;\n    for slot in 0 to 19 loop\n      base:=64+slot*5;bits:=number(p,base+4);\n      if bits=0 then\n        for i in 0 to 4 loop if p(base+i)/=0 then return false;end if;end loop;\n        if slot=0 or (slot>=1 and slot<=depth*4) or (slot=17 and mode/=0) or (slot=18 and mode/=2) or (slot=19 and mode=2) then return false;end if;\n      else\n        if bits/=4 and bits/=8 then return false;end if;\n        if not fits(p(base+3),8) or p(base+3)<-50 or p(base+3)>50 then return false;end if;\n        k:=128;n:=128;\n        if slot=0 then k:=36;if p(3)=1 then k:=80;end if;\n        elsif slot=17 then n:=1;\n        elsif slot>=18 then n:=classes;\n        elsif (slot-1) mod 4=0 then n:=384;\n        elsif (slot-1) mod 4=2 then n:=256;\n        elsif (slot-1) mod 4=3 then k:=256;end if;\n        span:=(n*k*bits+63)/64;\n        if number(p,base)>number(p,16) or number(p,base)+span>number(p,16) or\n           number(p,base+1)>number(p,17) or number(p,base+1)+n>number(p,17) or\n           number(p,base+2)>number(p,18) or number(p,base+2)+n>number(p,18) then return false;end if;\n      end if;\n    end loop;\n    return true;\n  end;\n"

def render():
 s=json.loads((ROOT/'rtl/config/image_schema.json').read_text())
 lines=['-- Generated by emit_image_pkg.py from image_schema.json. ABI2 logical words.','library ieee;use ieee.std_logic_1164.all;use ieee.numeric_std.all;','use work.eat_config_pkg.all;use work.eat_types_pkg.all;use work.eat_math_pkg.all;','package eat_image_pkg is',f"  constant C_IMAGE_BANK_WORDS : positive := {s['bank_words']};",f"  constant C_IMAGE_PROFILE_WORDS : positive := {s['profile_words']};",f"  constant C_IMAGE_MAGIC : unsigned(31 downto 0) := x\"{s['magic']:08x}\";",'  function region_offset(kind:constant_kind_t) return natural;','  function region_words(kind:constant_kind_t) return positive;','  function image_address(kind:constant_kind_t;bank:bank_id_t;offset:mem_addr_t) return mem_addr_t;','  subtype profile_t is wide_vec_t(0 to C_IMAGE_PROFILE_WORDS-1);','  function valid_constant(kind:constant_kind_t;value:wide_t) return boolean;','  function number(p:profile_t;i:natural) return natural;','  function valid_profile(p:profile_t;identity:identity_t) return boolean;','end package;','package body eat_image_pkg is']
 for function,key,typ in [('region_offset','offset','natural'),('region_words','words','positive')]:
  lines += [f'  function {function}(kind:constant_kind_t) return {typ} is','  begin case kind is']
  lines += [f"    when CONST_{r['kind']} => return {r[key]};" for r in s['regions']]
  lines += ['  end case;end;']
 lines += ['  function image_address(kind:constant_kind_t;bank:bank_id_t;offset:mem_addr_t) return mem_addr_t is','  begin return to_unsigned(to_integer(bank)*C_IMAGE_BANK_WORDS+region_offset(kind)+to_integer(offset),C_MEM_ADDR_BITS);end;',PROFILE_FUNCTIONS,'end package body;','']
 return '\n'.join(lines)
def main():
 p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');p.add_argument('--output',type=Path,default=ROOT/'rtl/pkg/eat_image_pkg.vhd');a=p.parse_args();text=render()
 if a.check:
  if a.output.read_text()!=text:raise SystemExit('Stale image package')
 else:a.output.write_text(text)
if __name__=='__main__':main()
